"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["18007"],{47362(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.estrutura_formulario.bloco_repetido","status":422,"titulo":"O bloco aparece mais de uma vez no formul\xe1rio"},"descricao":{"codigo":"uniplus.estrutura_formulario.bloco_repetido","requisitos":[],"oQueAconteceu":["Duas ou mais p\xe1ginas do formul\xe1rio declaram o mesmo bloco de sistema (`COMPROVACAO_DOCUMENTAL`, `MODALIDADES_CALCULADAS` ou `REVISAO_E_ACEITE`). Cada bloco entra uma vez, porque o sistema monta o bloco a partir da configura\xe7\xe3o do processo e n\xe3o h\xe1 o que repetir. A mensagem \xe9 \\"O bloco aparece mais de uma vez no formul\xe1rio.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `paginas[i].bloco`; nos modelos de formul\xe1rio o `field` come\xe7a por `conteudo.`. Nada \xe9 gravado. A entrada aponta cada repeti\xe7\xe3o, da segunda em diante, e a primeira ocorr\xeancia do bloco fica de fora da recusa. O bloco que a declara\xe7\xe3o do formul\xe1rio nem admite \xe9 recusado antes como [bloco n\xe3o admitido](/erros/uniplus.estrutura_formulario.bloco_nao_admitido), a cada ocorr\xeancia, sem passar por esta confer\xeancia.","A estrutura das p\xe1ginas s\xf3 \xe9 conferida quando todas as p\xe1ginas t\xeam forma v\xe1lida, e as recusas da estrutura saem juntas, na mesma lista. Na grava\xe7\xe3o do formul\xe1rio do processo, a forma de cada p\xe1gina \xe9 conferida primeiro e, havendo recusa, a estrutura s\xf3 \xe9 conferida se todas as p\xe1ginas foram formadas. No modelo, a estrutura s\xf3 \xe9 conferida quando o conte\xfado n\xe3o tem nenhuma outra recusa de forma, e os itens s\xe3o conferidos contra as p\xe1ginas s\xf3 depois que a estrutura das p\xe1ginas passa.","Nos modelos de formul\xe1rio, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Mantenha uma s\xf3 p\xe1gina para cada bloco e retire as repetidas. Depois disso, grave de novo."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o do formul\xe1rio do processo"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Estrutura formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);